# États ou limites décrits mais pas encore codés (affichés « à coder » dans la doc).
PENDING = {
 "Button": ["chargement"], "SearchBar": ["chargement", "horsConnexion"], "TextField": ["desactive"], "Tabs": ["desactive"],
 "OfferRow": ["chargement"], "BottomNav": ["limite : 99+"], "Banner": [], "EmptyState": [],
}
for n, p in PENDING.items(): C[n]["pending"] = p
REQ = ["status", "flutter", "role", "props", "states", "limits", "a11y", "tokens"]
for n, c in C.items():
    missing = [k for k in REQ if not c.get(k)]
    assert not missing, (n, missing)
    assert c["states"]["defaut"], n
json.dump(C, open(sys.argv[1], "w"), ensure_ascii=False, indent=1)
print(len(C), "contrats")
